export default function TechIcon({ name }: { name: string }) {
    // Check for exact matches first
    const iconKey = Object.keys(iconMap).find((key) =>
        name.toLowerCase().includes(key.toLowerCase())
    );

    if (iconKey) {
        return (
            <div className="w-5 h-5 flex items-center justify-center text-accent">
                {iconMap[iconKey]}
            </div>
        );
    }

    // Fallback to lucide icons
    if (name.includes("React") || name.includes("Flutter")) return <Smartphone size={20} />;
    if (name.includes("Node") || name.includes("Django") || name.includes("Go"))
        return <Server size={20} />;
    if (name.includes("SQL") || name.includes("Data") || name.includes("MySQL"))
        return <Database size={20} />;
    return <Code size={20} />;
}
